def mesures_retenues(mesures, seuil):
    resultat = []
    for mesure in mesures:
        if mesure >= seuil:
            resultat.append(mesure)
    return resultat

def noms_distincts(noms):
    uniques = set()
    for nom in noms:
        propre = nom.strip().lower()
        if propre != "":
            uniques.add(propre)
    return sorted(uniques)

def bilan_mesures(valeurs, seuil):
    total = 0
    nombre = 0
    for valeur in valeurs:
        if valeur >= seuil:
            total = total + valeur
            nombre = nombre + 1
    return {"total":total, "nombre":nombre}

def premiere_mesure(valeurs, seuil):
    for valeur in valeurs:
        if valeur >= seuil:
            return valeur
    return None
